    chk(name, sc, '↶ Put back is refused and says so -- [byte for byte as it was, questions, on screen, said]', J(putBack(B)), J([true, 0, 'S1', true]));
    const s0 = state(B.ev); const r = await B.ev('driveStorePull(true)'); await pause(5);
