  const fy28 = () => JSON.parse(R.ev(`JSON.stringify(((MS.years[2028]||{}).custom||[]).map(function(c){ return [c.id, c.title, c.prior||null]; }))`));
  const r1 = roll(['NEW-1', 'NEW-2']);
